     1|/**
     2| * IVX Task Execution State Machine
     3| *
     4| * Owner mandate 2026-07-20 Phase 1: replace the simplified task status logic
     5| * with a real 17-state state machine that enforces legal transitions and the
     6| * owner's completion rules.
     7| *
     8| * Rules (enforced in canTransition + assertCanTransition):
     9| *   - DEPLOYED means only that a deployment occurred.
    10| *   - VERIFIED means the requested acceptance tests passed.
    11| *   - A task cannot become VERIFIED from /health alone.
    12| *   - A development task cannot become VERIFIED when no code changed unless the
    13| *     system proves that configuration, data, infrastructure, or an external
    14| *     dependency was the actual cause.
    15| *   - If no work was completed, status must be BLOCKED, FAILED, or
    16| *     NO_CHANGE_REQUIRED.
    17| *   - Never display "development completed" when the code diff is empty.
    18| *
    19| * This module is intentionally runtime-free and does NOT import worker types,
    20| * to avoid circular dependencies.
    21| */
    22|
    23|export const IVX_TASK_STATE_MACHINE_MARKER = 'ivx-task-state-machine-2026-07-20';
    24|
    25|export type IVXTaskState =
    26|  | 'RECEIVED'
    27|  | 'ANALYZING'
    28|  | 'REPRODUCING'
    29|  | 'ROOT_CAUSE_IDENTIFIED'
    30|  | 'IMPLEMENTING'
    31|  | 'CODE_CHANGED'
    32|  | 'TESTING'
    33|  | 'QA_REQUIRED'
    34|  | 'QA_IN_PROGRESS'
    35|  | 'READY_TO_DEPLOY'
    36|  | 'DEPLOYING'
    37|  | 'DEPLOYED'
    38|  | 'PRODUCTION_VERIFYING'
    39|  | 'VERIFIED'
    40|  | 'BLOCKED'
    41|  | 'FAILED'
    42|  | 'NO_CHANGE_REQUIRED';
    43|
    44|export const ALL_TASK_STATES: readonly IVXTaskState[] = [
    45|  'RECEIVED',
    46|  'ANALYZING',
    47|  'REPRODUCING',
    48|  'ROOT_CAUSE_IDENTIFIED',
    49|  'IMPLEMENTING',
    50|  'CODE_CHANGED',
    51|  'TESTING',
    52|  'QA_REQUIRED',
    53|  'QA_IN_PROGRESS',
    54|  'READY_TO_DEPLOY',
    55|  'DEPLOYING',
    56|  'DEPLOYED',
    57|  'PRODUCTION_VERIFYING',
    58|  'VERIFIED',
    59|  'BLOCKED',
    60|  'FAILED',
    61|  'NO_CHANGE_REQUIRED',
    62|] as const;
    63|
    64|export const TERMINAL_TASK_STATES: ReadonlySet<IVXTaskState> = new Set([
    65|  'VERIFIED',
    66|  'BLOCKED',
    67|  'FAILED',
    68|  'NO_CHANGE_REQUIRED',
    69|]);
    70|
    71|/**
    72| * Legal forward transitions. A task may not skip from RECEIVED straight to
    73| * DEPLOYED or VERIFIED — it must walk the senior-developer loop.
    74| */
    75|const LEGAL_TRANSITIONS: ReadonlyMap<IVXTaskState, ReadonlySet<IVXTaskState>> = new Map([
    76|  ['RECEIVED', new Set(['ANALYZING', 'BLOCKED', 'FAILED', 'NO_CHANGE_REQUIRED'])],
    77|  ['ANALYZING', new Set(['REPRODUCING', 'ROOT_CAUSE_IDENTIFIED', 'BLOCKED', 'FAILED', 'NO_CHANGE_REQUIRED'])],
    78|  ['REPRODUCING', new Set(['ROOT_CAUSE_IDENTIFIED', 'BLOCKED', 'FAILED', 'NO_CHANGE_REQUIRED'])],
    79|  ['ROOT_CAUSE_IDENTIFIED', new Set(['IMPLEMENTING', 'BLOCKED', 'FAILED', 'NO_CHANGE_REQUIRED'])],
    80|  ['IMPLEMENTING', new Set(['CODE_CHANGED', 'BLOCKED', 'FAILED', 'NO_CHANGE_REQUIRED'])],
    81|  ['CODE_CHANGED', new Set(['TESTING', 'BLOCKED', 'FAILED'])],
    82|  ['TESTING', new Set(['QA_REQUIRED', 'READY_TO_DEPLOY', 'BLOCKED', 'FAILED'])],
    83|  ['QA_REQUIRED', new Set(['QA_IN_PROGRESS', 'BLOCKED', 'FAILED'])],
    84|  ['QA_IN_PROGRESS', new Set(['READY_TO_DEPLOY', 'BLOCKED', 'FAILED'])],
    85|  ['READY_TO_DEPLOY', new Set(['DEPLOYING', 'BLOCKED', 'FAILED'])],
    86|  ['DEPLOYING', new Set(['DEPLOYED', 'BLOCKED', 'FAILED'])],
    87|  ['DEPLOYED', new Set(['PRODUCTION_VERIFYING', 'BLOCKED', 'FAILED'])],
    88|  ['PRODUCTION_VERIFYING', new Set(['VERIFIED', 'BLOCKED', 'FAILED'])],
    89|  ['VERIFIED', new Set()],
    90|  ['BLOCKED', new Set()],
    91|  ['FAILED', new Set()],
    92|  ['NO_CHANGE_REQUIRED', new Set()],
    93|]);
    94|
    95|/**
    96| * Transition guard: verifies a transition is legal per the state machine.
    97| * Also enforces the owner's completion rules:
    98| *   - A development task cannot transition to VERIFIED with an empty diff
    99| *     unless an external cause is proven.
   100| *   - A task cannot transition to VERIFIED from /health alone (requires
   101| *     featureVerificationOk).
   102| *   - A task cannot transition to VERIFIED with no deployment for development
   103| *     tasks.
   104| */
   105|export type IVXTransitionGuardInput = {
   106|  from: IVXTaskState;
   107|  to: IVXTaskState;
   108|  isDevelopmentTask: boolean;
   109|  filesChangedCount: number;
   110|  testsRun: boolean;
   111|  testsPassed: boolean;
   112|  deployId: string | null;
   113|  productionHealthOk: boolean;
   114|  featureVerificationOk: boolean | null;
   115|  externalCauseProven: boolean;
   116|};
   117|
   118|export type IVXTransitionGuardResult = {
   119|  ok: boolean;
   120|  legal: boolean;
   121|  reasons: string[];
   122|  from: IVXTaskState;
   123|  to: IVXTaskState;
   124|};
   125|
   126|export function isTerminalTaskState(state: IVXTaskState): boolean {
   127|  return TERMINAL_TASK_STATES.has(state);
   128|}
   129|
   130|export function canTransition(from: IVXTaskState, to: IVXTaskState): boolean {
   131|  const allowed = LEGAL_TRANSITIONS.get(from);
   132|  return allowed ? allowed.has(to) : false;
   133|}
   134|
   135|export function assertCanTransition(input: IVXTransitionGuardInput): IVXTransitionGuardResult {
   136|  const reasons: string[] = [];
   137|  const { from, to } = input;
   138|
   139|  // Check structural legality first.
   140|  if (!canTransition(from, to)) {
   141|    reasons.push(`Illegal transition: ${from} -> ${to} is not a permitted forward transition.`);
   142|    return { ok: false, legal: false, reasons, from, to };
   143|  }
   144|
   145|  // Enforce completion rules on entry to VERIFIED.
   146|  if (to === 'VERIFIED') {
   147|    if (input.isDevelopmentTask) {
   148|      if (input.filesChangedCount === 0 && !input.externalCauseProven) {
   149|        reasons.push(
   150|          'A development task cannot become VERIFIED when no code changed unless an external cause (config/data/infra) is proven.',
   151|        );
   152|        return { ok: false, legal: true, reasons, from, to };
   153|      }
   154|      if (input.filesChangedCount === 0 && input.externalCauseProven && !input.deployId) {
   155|        reasons.push('External-cause development task requires a deployment before VERIFIED.');
   156|        return { ok: false, legal: true, reasons, from, to };
   157|      }
   158|      if (input.filesChangedCount > 0) {
   159|        if (!input.testsRun) {
   160|          reasons.push('Files changed but tests were not run — cannot become VERIFIED.');
   161|          return { ok: false, legal: true, reasons, from, to };
   162|        }
   163|        if (!input.testsPassed) {
   164|          reasons.push('Files changed but tests failed — cannot become VERIFIED.');
   165|          return { ok: false, legal: true, reasons, from, to };
   166|        }
   167|        if (!input.deployId) {
   168|          reasons.push('Files changed but no deployment occurred — cannot become VERIFIED.');
   169|          return { ok: false, legal: true, reasons, from, to };
   170|        }
   171|        if (!input.productionHealthOk) {
   172|          reasons.push('Files changed but production health is not confirmed — cannot become VERIFIED.');
   173|          return { ok: false, legal: true, reasons, from, to };
   174|        }
   175|      }
   176|    }
   177|    // A task cannot become VERIFIED from /health alone.
   178|    if (input.featureVerificationOk === false) {
   179|      reasons.push('Feature verification failed — a task cannot become VERIFIED from /health alone.');
   180|      return { ok: false, legal: true, reasons, from, to };
   181|    }
   182|    if (input.featureVerificationOk === null && input.isDevelopmentTask) {
   183|      reasons.push('Feature verification was not performed — cannot become VERIFIED without it.');
   184|      return { ok: false, legal: true, reasons, from, to };
   185|    }
   186|  }
   187|
   188|  // Enforce entry to DEPLOYED: requires a deployId.
   189|  if (to === 'DEPLOYED' && !input.deployId) {
   190|    reasons.push('Cannot enter DEPLOYED without a deployId.');
   191|    return { ok: false, legal: true, reasons, from, to };
   192|  }
   193|
   194|  // Enforce entry to CODE_CHANGED: requires filesChangedCount > 0.
   195|  if (to === 'CODE_CHANGED' && input.filesChangedCount === 0) {
   196|    reasons.push('Cannot enter CODE_CHANGED with an empty diff — never display "development completed" when the code diff is empty.');
   197|    return { ok: false, legal: true, reasons, from, to };
   198|  }
   199|
   200|  return { ok: true, legal: true, reasons: [], from, to };
   201|}
   202|
   203|/**
   204| * Compute the honest terminal state when no work was completed.
   205| * Per the owner: "If no work was completed, status must be BLOCKED, FAILED, or
   206| * NO_CHANGE_REQUIRED."
   207| */
   208|export function terminalStateForNoWork(
   209|  deployId: string | null,
   210|  productionHealthOk: boolean,
   211|  error: string | null,
   212|): IVXTaskState {
   213|  if (error && /blocked|missing|denied|revoked|expired|unauthorized/i.test(error)) {
   214|    return 'BLOCKED';
   215|  }
   216|  if (error) {
   217|    return 'FAILED';
   218|  }
   219|  if (deployId && productionHealthOk) {
   220|    // A redeploy occurred but no code changed — honest state is NO_CHANGE_REQUIRED,
   221|    // NOT VERIFIED. The completion validator will report DEPLOYED_ONLY.
   222|    return 'NO_CHANGE_REQUIRED';
   223|  }
   224|  return 'NO_CHANGE_REQUIRED';
   225|}
   226|
   227|/**
   228| * The 18-step senior-developer loop. Each step maps to a state transition.
   229| * This is the canonical sequence — the worker must not skip from request to
   230| * deployment.
   231| */
   232|export const SENIOR_DEVELOPER_LOOP_STEPS: readonly { step: number; name: string; enterState: IVXTaskState }[] = [
   233|  { step: 1, name: 'Understand the requested behavior', enterState: 'ANALYZING' },
   234|  { step: 2, name: 'Retrieve relevant project context', enterState: 'ANALYZING' },
   235|  { step: 3, name: 'Inspect the actual code', enterState: 'ANALYZING' },
   236|  { step: 4, name: 'Locate related files and services', enterState: 'ANALYZING' },
   237|  { step: 5, name: 'Reproduce the problem', enterState: 'REPRODUCING' },
   238|  { step: 6, name: 'Record baseline behavior', enterState: 'REPRODUCING' },
   239|  { step: 7, name: 'Identify the root cause', enterState: 'ROOT_CAUSE_IDENTIFIED' },
   240|  { step: 8, name: 'Create an implementation plan', enterState: 'ROOT_CAUSE_IDENTIFIED' },
   241|  { step: 9, name: 'Modify the correct files', enterState: 'IMPLEMENTING' },
   242|  { step: 10, name: 'Run static checks', enterState: 'TESTING' },
   243|  { step: 11, name: 'Run unit and integration tests', enterState: 'TESTING' },
   244|  { step: 12, name: 'Run targeted regression tests', enterState: 'TESTING' },
   245|  { step: 13, name: 'Build the application', enterState: 'TESTING' },
   246|  { step: 14, name: 'Test on the required platform', enterState: 'QA_IN_PROGRESS' },
   247|  { step: 15, name: 'Commit the changes', enterState: 'READY_TO_DEPLOY' },
   248|  { step: 16, name: 'Deploy the exact commit', enterState: 'DEPLOYING' },
   249|  { step: 17, name: 'Verify production behavior', enterState: 'PRODUCTION_VERIFYING' },
   250|  { step: 18, name: 'Return evidence and remaining risks', enterState: 'VERIFIED' },
   251|] as const;
   252|
   253|/**
   254| * Map a worker stage name to a task state. This bridges the worker's
   255| * free-form stage strings to the canonical state machine.
   256| */
   257|export function stageToTaskState(stage: string | null | undefined): IVXTaskState {
   258|  const s = (stage ?? '').toUpperCase().replace(/[^A-Z_]/g, '_');
   259|  if (s.includes('RECEIVED') || s.includes('QUEUED') || s.includes('PENDING')) return 'RECEIVED';
   260|  if (s.includes('ANALYZ') || s.includes('INSPECT') || s.includes('INDEX')) return 'ANALYZING';
   261|  if (s.includes('REPRODUC') || s.includes('BASELINE')) return 'REPRODUCING';
   262|  if (s.includes('ROOT_CAUSE') || s.includes('ROOTCAUSE') || s.includes('PLAN')) return 'ROOT_CAUSE_IDENTIFIED';
   263|  if (s.includes('IMPLEMENT') || s.includes('PATCH') || s.includes('EDIT')) return 'IMPLEMENTING';
   264|  if (s.includes('CODE_CHANGED') || s.includes('CODECHANGE')) return 'CODE_CHANGED';
   265|  if (s.includes('TEST')) return 'TESTING';
   266|  if (s.includes('QA_REQUIRED') || s.includes('QAREQUIRED')) return 'QA_REQUIRED';
   267|  if (s.includes('QA_IN_PROGRESS') || s.includes('QAINPROGRESS') || s.includes('QA')) return 'QA_IN_PROGRESS';
   268|  if (s.includes('READY_TO_DEPLOY') || s.includes('READYTODEPLOY') || s.includes('READY')) return 'READY_TO_DEPLOY';
   269|  if (s.includes('DEPLOYING') || s.includes('DEPLOY_IN_PROGRESS')) return 'DEPLOYING';
   270|  if (s.includes('DEPLOYED') && !s.includes('VERIFY')) return 'DEPLOYED';
   271|  if (s.includes('PRODUCTION_VERIFY') || s.includes('VERIFYING') || s.includes('VERIFY')) return 'PRODUCTION_VERIFYING';
   272|  if (s.includes('VERIFIED') || s.includes('COMPLETE')) return 'VERIFIED';
   273|  if (s.includes('BLOCKED')) return 'BLOCKED';
   274|  if (s.includes('FAILED') || s.includes('ERROR')) return 'FAILED';
   275|  if (s.includes('NO_CHANGE') || s.includes('NOCHANGE')) return 'NO_CHANGE_REQUIRED';
   276|  return 'RECEIVED';
   277|}

