     1|/**
     2| * IVX Structured Execution Record
     3| *
     4| * Owner mandate 2026-07-20 Phase 11: store a structured execution record for
     5| * every task with 22 fields. The IVX response must be generated FROM this
     6| * record — the response engine must not invent actions that are absent from
     7| * the execution record.
     8| *
     9| * This module is runtime-free and does NOT import worker types, to avoid
    10| * circular dependencies. It defines the canonical record shape + helpers to
    11| * build and validate it.
    12| */
    13|
    14|export const IVX_EXECUTION_RECORD_MARKER = 'ivx-execution-record-2026-07-20';
    15|
    16|import type { IVXTaskState, IVXTaskType } from './ivx-completion-validator';
    17|
    18|export type IVXExecutionRecord = {
    19|  task_id: string;
    20|  parent_task_id: string | null;
    21|  task_type: IVXTaskType;
    22|  user_request: string;
    23|  acceptance_criteria: string[];
    24|  status: IVXTaskState;
    25|  analysis: string | null;
    26|  reproduction_steps: string[];
    27|  root_cause: string | null;
    28|  implementation_plan: string | null;
    29|  files_inspected: string[];
    30|  files_changed: string[];
    31|  commands: IVXExecutionCommand[];
    32|  tests: IVXExecutionTestResult[];
    33|  qa_results: IVXExecutionQAResult[];
    34|  commit_sha: string | null;
    35|  deployment_id: string | null;
    36|  production_checks: IVXExecutionProductionCheck[];
    37|  evidence: IVXExecutionEvidenceEntry[];
    38|  blockers: string[];
    39|  remaining_work: string[];
    40|  started_at: string;
    41|  completed_at: string | null;
    42|  verified_at: string | null;
    43|};
    44|
    45|export type IVXExecutionCommand = {
    46|  command: string;
    47|  exitCode: number | null;
    48|  outputPreview: string;
    49|  startedAt: string;
    50|  finishedAt: string | null;
    51|};
    52|
    53|export type IVXExecutionTestResult = {
    54|  name: string;
    55|  command: string;
    56|  passed: boolean;
    57|  passedCount: number | null;
    58|  failedCount: number | null;
    59|  durationMs: number | null;
    60|  outputPreview: string;
    61|};
    62|
    63|export type IVXExecutionQAResult = {
    64|  platform: 'android' | 'ios' | 'web' | 'backend' | 'device';
    65|  name: string;
    66|  passed: boolean | null;
    67|  evidence: string;
    68|  notes: string;
    69|};
    70|
    71|export type IVXExecutionProductionCheck = {
    72|  name: string;
    73|  url: string;
    74|  httpStatus: number | null;
    75|  ok: boolean;
    76|  detail: string;
    77|  checkedAt: string;
    78|};
    79|
    80|export type IVXExecutionEvidenceEntry = {
    81|  kind: 'commit' | 'deploy' | 'health' | 'feature' | 'test' | 'qa' | 'diff' | 'log' | 'screenshot' | 'config';
    82|  label: string;
    83|  value: string;
    84|  timestamp: string;
    85|  verified: boolean;
    86|};
    87|
    88|export const EXECUTION_RECORD_REQUIRED_FIELDS: readonly (keyof IVXExecutionRecord)[] = [
    89|  'task_id',
    90|  'parent_task_id',
    91|  'task_type',
    92|  'user_request',
    93|  'acceptance_criteria',
    94|  'status',
    95|  'analysis',
    96|  'reproduction_steps',
    97|  'root_cause',
    98|  'implementation_plan',
    99|  'files_inspected',
   100|  'files_changed',
   101|  'commands',
   102|  'tests',
   103|  'qa_results',
   104|  'commit_sha',
   105|  'deployment_id',
   106|  'production_checks',
   107|  'evidence',
   108|  'blockers',
   109|  'remaining_work',
   110|  'started_at',
   111|  'completed_at',
   112|  'verified_at',
   113|] as const;
   114|
   115|/**
   116| * Create a fresh execution record for a new task.
   117| */
   118|export function createExecutionRecord(input: {
   119|  task_id: string;
   120|  parent_task_id?: string | null;
   121|  task_type: IVXTaskType;
   122|  user_request: string;
   123|  acceptance_criteria?: string[];
   124|}): IVXExecutionRecord {
   125|  return {
   126|    task_id: input.task_id,
   127|    parent_task_id: input.parent_task_id ?? null,
   128|    task_type: input.task_type,
   129|    user_request: input.user_request,
   130|    acceptance_criteria: input.acceptance_criteria ?? [],
   131|    status: 'RECEIVED',
   132|    analysis: null,
   133|    reproduction_steps: [],
   134|    root_cause: null,
   135|    implementation_plan: null,
   136|    files_inspected: [],
   137|    files_changed: [],
   138|    commands: [],
   139|    tests: [],
   140|    qa_results: [],
   141|    commit_sha: null,
   142|    deployment_id: null,
   143|    production_checks: [],
   144|    evidence: [],
   145|    blockers: [],
   146|    remaining_work: [],
   147|    started_at: new Date().toISOString(),
   148|    completed_at: null,
   149|    verified_at: null,
   150|  };
   151|}
   152|
   153|/**
   154| * Validate that an execution record has all 22 required fields and that the
   155| * values are internally consistent. The response engine must call this before
   156| * generating a response from the record.
   157| */
   158|export type IVXExecutionRecordValidation = {
   159|  ok: boolean;
   160|  missingFields: string[];
   161|  inconsistencies: string[];
   162|};
   163|
   164|export function validateExecutionRecord(record: Partial<IVXExecutionRecord>): IVXExecutionRecordValidation {
   165|  const missingFields: string[] = [];
   166|  for (const field of EXECUTION_RECORD_REQUIRED_FIELDS) {
   167|    if (record[field] === undefined || record[field] === null) {
   168|      // completed_at and verified_at may be null for non-terminal tasks.
   169|      if (field === 'completed_at' || field === 'verified_at') continue;
   170|      // analysis, root_cause, implementation_plan may be null until reached.
   171|      if (field === 'analysis' || field === 'root_cause' || field === 'implementation_plan') continue;
   172|      // parent_task_id may be null.
   173|      if (field === 'parent_task_id') continue;
   174|      // commit_sha, deployment_id may be null until deploy.
   175|      if (field === 'commit_sha' || field === 'deployment_id') continue;
   176|      missingFields.push(field);
   177|    }
   178|  }
   179|
   180|  const inconsistencies: string[] = [];
   181|  if (record.status === 'VERIFIED') {
   182|    if (!record.verified_at) {
   183|      inconsistencies.push('VERIFIED status but verified_at is null.');
   184|    }
   185|    if (record.task_type === 'CODE_FIX' || record.task_type === 'FEATURE' || record.task_type === 'UI_FIX') {
   186|      if ((record.files_changed ?? []).length === 0 && !record.root_cause?.toLowerCase().includes('external')) {
   187|        inconsistencies.push('VERIFIED for a development task with no files changed and no external cause proven.');
   188|      }
   189|    }
   190|    const hasFeatureEvidence = (record.evidence ?? []).some((e) => e.kind === 'feature' && e.verified);
   191|    if (!hasFeatureEvidence && (record.task_type === 'CODE_FIX' || record.task_type === 'FEATURE' || record.task_type === 'UI_FIX')) {
   192|      inconsistencies.push('VERIFIED for a development task with no feature-verification evidence.');
   193|    }
   194|  }
   195|  if (record.status === 'DEPLOYED' && !record.deployment_id) {
   196|    inconsistencies.push('DEPLOYED status but deployment_id is null.');
   197|  }
   198|  if (record.status === 'CODE_CHANGED' && (record.files_changed ?? []).length === 0) {
   199|    inconsistencies.push('CODE_CHANGED status but files_changed is empty.');
   200|  }
   201|
   202|  return {
   203|    ok: missingFields.length === 0 && inconsistencies.length === 0,
   204|    missingFields,
   205|    inconsistencies,
   206|  };
   207|}
   208|
   209|/**
   210| * Append a command result to the record (immutable copy).
   211| */
   212|export function appendCommand(record: IVXExecutionRecord, cmd: IVXExecutionCommand): IVXExecutionRecord {
   213|  return { ...record, commands: [...record.commands, cmd] };
   214|}
   215|
   216|/**
   217| * Append a test result to the record (immutable copy).
   218| */
   219|export function appendTestResult(record: IVXExecutionRecord, test: IVXExecutionTestResult): IVXExecutionRecord {
   220|  return { ...record, tests: [...record.tests, test] };
   221|}
   222|
   223|/**
   224| * Append a QA result to the record (immutable copy).
   225| */
   226|export function appendQAResult(record: IVXExecutionRecord, qa: IVXExecutionQAResult): IVXExecutionRecord {
   227|  return { ...record, qa_results: [...record.qa_results, qa] };
   228|}
   229|
   230|/**
   231| * Append an evidence entry to the record (immutable copy).
