   368|
   369|async function githubLedgerRead(): Promise<LedgerDoc | null> {
   370|  const token = ledgerGithubToken();
   371|  if (!token) return null;
   372|  try {
   373|    const res = await fetch(
   374|      `https://api.github.com/repos/${ledgerGithubRepo()}/contents/${LEDGER_FILE}?ref=${LEDGER_GITHUB_BRANCH}`,
   375|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   376|    );
   377|    if (!res.ok) return null;
   378|    const data = await res.json() as { content?: string };
   379|    if (!data.content) return null;
   380|    const decoded = Buffer.from(data.content, 'base64').toString('utf8');
   381|    const doc = JSON.parse(decoded) as LedgerDoc;
   382|    if (!Array.isArray(doc.entries)) return null;
   383|    return { ...doc, marker: IVX_SENIOR_DEV_WORKER_MARKER, durable: true };
   384|  } catch {
   385|    return null;
   386|  }
