   389|async function githubEnsureLedgerBranch(): Promise<boolean> {
   390|  const repo = ledgerGithubRepo();
   391|  try {
   392|    const refRes = await fetch(
   393|      `https://api.github.com/repos/${repo}/git/ref/heads/${LEDGER_GITHUB_BRANCH}`,
   394|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   395|    );
   396|    if (refRes.ok) return true;
   397|    const mainRes = await fetch(
   398|      `https://api.github.com/repos/${repo}/git/ref/heads/main`,
   399|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   400|    );
   401|    if (!mainRes.ok) return false;
   402|    const mainData = await mainRes.json() as { object?: { sha?: string } };
   403|    const baseSha = mainData.object?.sha;
   404|    if (!baseSha) return false;
   405|    const createRes = await fetch(`https://api.github.com/repos/${repo}/git/refs`, {
   406|      method: 'POST',
   407|      headers: ledgerGithubHeaders(),
   408|      body: JSON.stringify({ ref: `refs/heads/${LEDGER_GITHUB_BRANCH}`, sha: baseSha }),
   409|      signal: AbortSignal.timeout(10000),
   410|    });
   411|    return createRes.ok;
   412|  } catch {
   413|    return false;
   414|  }
   415|}
