   417|async function githubLedgerWrite(doc: LedgerDoc): Promise<boolean> {
   418|  const token = ledgerGithubToken();
   419|  if (!token) return false;
   420|  const repo = ledgerGithubRepo();
   421|  try {
   422|    if (!(await githubEnsureLedgerBranch())) return false;
   423|    let existingSha: string | undefined;
   424|    const currentRes = await fetch(
   425|      `https://api.github.com/repos/${repo}/contents/${LEDGER_FILE}?ref=${LEDGER_GITHUB_BRANCH}`,
   426|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   427|    );
   428|    if (currentRes.ok) {
   429|      const current = await currentRes.json() as { sha?: string };
   430|      existingSha = current.sha;
   431|    }
   432|    const putRes = await fetch(
   433|      `https://api.github.com/repos/${repo}/contents/${LEDGER_FILE}`,
   434|      {
   435|        method: 'PUT',
   436|        headers: ledgerGithubHeaders(),
   437|        body: JSON.stringify({
   438|          message: `chore(ledger): proof ledger update ${nowIso()}`,
   439|          content: Buffer.from(JSON.stringify(doc, null, 2), 'utf8').toString('base64'),
   440|          branch: LEDGER_GITHUB_BRANCH,
   441|          ...(existingSha ? { sha: existingSha } : {}),
   442|        }),
   443|        signal: AbortSignal.timeout(15000),
   444|      },
   445|    );
   446|    return putRes.ok;
   447|  } catch {
   448|    return false;
   449|  }
