   712|  for (const job of queue.jobs) {
   713|    if (!ACTIVE_STATUSES.has(job.status)) continue;
   714|    if (!job.startedAt) continue;
   715|    const startedAtMs = new Date(job.startedAt).getTime();
   716|    if (Number.isNaN(startedAtMs)) continue;
   717|    if (now - startedAtMs > STALE_JOB_TIMEOUT_MS) {
   718|      job.status = 'failed';
   719|      job.stage = 'FAILED';
   720|      job.stageDetail = `Job expired after ${Math.round(STALE_JOB_TIMEOUT_MS / 1000)}s of inactivity.`;
