   111|export function classifyTaskType(goal: string): IVXTaskType {
   112|  const normalized = (goal ?? '').toLowerCase();
   113|  if (/(audit|inspect|investigate|trace|root cause|diagnose|find why|report|explain|understand|analyze|analysis|why is|why does|why are|what is causing|what causes)/i.test(normalized)
