   115|    return 'INVESTIGATION';
   116|  }
   117|  if (/\b(deploy|redeploy|push live|release|rollout|render deploy)\b/i.test(normalized)
   118|      && !/(fix|bug|patch|feature|implement|ui|scroll|loading|chat|screen)/i.test(normalized)) {
   119|    return 'DEPLOYMENT';
   120|  }
   121|  if (/(qa|test|verify|acceptance|regression|check|validate|measure)/i.test(normalized)
   122|      && !/(fix|deploy|change|edit|apply|implement|patch|build|upgrade)/i.test(normalized)) {
   123|    return 'QA_ONLY';
   124|  }
   125|  if (/(configuration|config|env|environment variable|render env|setting|toggle)/i.test(normalized)) {
   126|    return 'CONFIGURATION_FIX';
   127|  }
   128|  if (/(infrastructure|server|database|redis|queue|render service|supabase project|migrate schema)/i.test(normalized)) {
