cd /home/user/rork-app && cat > /tmp/commit_version.mjs << 'EOF'
import { gzipSync } from 'node:zlib';
import { readFileSync } from 'node:fs';

const TOKEN = readFileSync('/tmp/owner_at', 'utf8').trim();
const files = [
  { path: 'expo/app.config.ts', message: 'IVX 16-phase wiring: version bump v1.4.24(56) -> v1.4.25(57) for chat pagination + 7-module wiring release' },
  { path: 'expo/android/app/build.gradle', message: 'IVX 16-phase wiring: version bump versionCode 56 -> 57, versionName 1.4.24 -> 1.4.25' },
];

for (const f of files) {
  const content = readFileSync('/home/user/rork-app/' + f.path, 'utf8');
  const gz = gzipSync(Buffer.from(content, 'utf8')).toString('base64');
  const body = {
    action: 'github_commit_file',
    input: { path: f.path, content: gz, contentEncoding: 'gzip-base64', message: f.message },
    confirm: true,
    confirmText: 'CONFIRM_IVX_GITHUB_WRITE',
  };
  const res = await fetch('https://api.ivxholding.com/api/ivx/developer-deploy/action', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${TOKEN}` },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(30000),
  });
  const text = await res.text();
  let parsed;
  try { parsed = JSON.parse(text); } catch { parsed = text.slice(0, 300); }
  const sha = parsed?.result?.github?.commitSha ? parsed.result.github.commitSha.slice(0, 12) : 'NONE';
  console.log(`[${res.status}] ${f.path} -> sha=${sha} ok=${parsed?.ok ?? '?'}`);
}
EOF
node /tmp/commit_version.mjs 2>&1 | tail -5

